#pragma once
#include "aether/install/store.hpp"

namespace aether::install {
// Windows registrations are reconstructible projections of the package journal.
// Every filename/command is generated by trusted code, never taken from an APK.
bool valid_shell_record(const InstalledApp &app);
std::shared_ptr<const void> hold_shell_registration();
// Derived only from validated committed journal history, never pending candidates.
// Both sets are sorted, distinct and bounded by the existing 4096-record limit.
struct ShellIconAliases {
    std::vector<std::uint64_t> generations;
    std::vector<std::string> committed_sha256;
};
// Reconstruct current artwork at historical Aether-owned icon paths for old pins.
// The selected active icon is excluded; no Windows-owned pin data is changed.
bool apply_shell_icon_aliases(const InstalledApp &selected, const std::filesystem::path &store,
                              const ShellIconAliases &aliases);
void validate_shell_icon_aliases(const InstalledApp &selected, const std::filesystem::path &store,
                                 const ShellIconAliases &aliases);
void remove_shell_icon_aliases(const InstalledApp &selected, const std::filesystem::path &store,
                               const ShellIconAliases &aliases);
void plan_shell_registration(InstalledApp &app, const std::filesystem::path &store,
                             const apk::Artwork *artwork = nullptr);
void plan_shell_update(const InstalledApp &previous, InstalledApp &candidate, const apk::Artwork &artwork,
                       const std::filesystem::path &store);
// Retire only obsolete icon/shortcut paths. The active app's shared uninstall
// key is never removed by update cleanup.
void retire_shell_update(const InstalledApp &retired, const InstalledApp &current,
                         const std::filesystem::path &store, const ShellIconAliases *aliases = nullptr);
void apply_shell_registration(const InstalledApp &app, const std::filesystem::path &store,
                              const apk::Artwork *artwork = nullptr);
// Only a journal-reconstructed update pair permits changing a shared icon's
// contents. Ordinary registration/repair keeps its exact-content ownership rule.
void apply_shell_update(const InstalledApp &selected, const InstalledApp &other,
                        const std::filesystem::path &store);
void validate_shell_ownership(const InstalledApp &app, const std::filesystem::path &store);
bool inspect_shell_registration(const InstalledApp &app, const std::filesystem::path &store);
// Read-only: requires the explicit toast marker, typed shortcut CLSID and exact
// owned local-server projection. Legacy core-only registrations return false.
bool inspect_notification_registration(const InstalledApp &app, const std::filesystem::path &store);
// Explicit repair only: revalidate the current owned projections, then request
// Shell cache updates without rewriting intact registration/icon/shortcut bytes.
// The notification API provides no acknowledgement of Explorer cache convergence.
void notify_shell_repair(const InstalledApp &app, const std::filesystem::path &store);
void remove_shell_registration(const InstalledApp &app, const std::filesystem::path &store);
std::filesystem::path shell_launcher();
std::filesystem::path programs_directory();
security::InstalledRelaunch shell_relaunch(const InstalledApp &app, const std::filesystem::path &store);
// Read-only Windows locator followed by authoritative journal/projection
// revalidation. The returned path grants no launch authority or session lease;
// callers reopen and revalidate before preparing an installed session.
std::filesystem::path registered_shell_store(std::string_view id);
security::InstalledActivity prepare_shell_relaunch(std::string_view id);
std::wstring shell_arguments(const InstalledApp &app, const std::filesystem::path &store,
                             std::wstring_view operation);
std::wstring quote_windows_argument(std::wstring_view value);
} // namespace aether::install
